# 生成虚构的中文长资料母库（约 14,000 字），全部人名 / 学校 / 单位均为虚构，仅用于测试
import random, os
random.seed(7)
C=[f'模拟课程{i+1}' for i in range(76)]
NAMES=['高等数学A','线性代数','大学物理','工程制图','理论力学','材料力学','工程热力学','流体力学','传热学','电工学','机械原理','机械设计','船舶柴油机','船舶辅机','轮机自动化','液压与气压传动','控制工程基础','测试技术','单片机原理','C语言程序设计']
for i,n in enumerate(NAMES): C[i]=n
out=[]
w=out.append
w('个人求职母库（完整版，测试用虚构资料）\n')
w('姓名：测试用户庚　性别：男　出生年月：2001-03　籍贯：模拟省临江市　政治面貌：共青团员\n电话：138-0000-0000　邮箱：gengtest@example.com　所在地：吉隆坡\n求职方向：工业自动化 / 机器人工程师\n')
w('一、教育经历\n')
w('1. 东临海事大学（Donglin Maritime University）\n专业：轮机工程（Marine Engineering）　学位：工学学士（Bachelor of Engineering）\n时间：2019.09—2023.06　学位已于 2023.06 实际授予。\nGPA 3.4/4.0，专业排名前 30%。\n备注：学位证编号待核实，证书扫描件在邮箱里。\n')
w('2. Sunbay University Malaysia（桑湾大学马来西亚分校）\nMaster of Applied Engineering（应用工程硕士），方向：Industrial AI & Robotics（工业人工智能与机器人）\n时间：2026.02—预计 2027.01（预计授予学位时间，尚未授予）\n')
w('二、本科成绩单（共 76 门课程，全部列出）\n')
for i,c in enumerate(C): w(f'{i+1}. {c}　学分 {(i%4)+1}　成绩 {60+random.randint(10,38)}')
w('\n三、工作经历\n')
w('【正式工作】北岭生物科技股份有限公司　自动化生产技术员　2023.10—2024.06\n（注：这一段其实就是下面的实习，简历里写成了工作经历，需核实合同性质。）\n')
w('【实习】北岭生物科技股份有限公司（Beiling Biotech Co., Ltd.）　自动化生产技术员（实习）　2023.10—2024.06\n')
for k in range(12): w(f'- 负责灌装线第 {k+1} 号工位的 PLC 程序维护与参数调整，记录设备点检表，配合班组完成换型调试，平均换型时间缩短约 {5+k} 分钟；整理故障案例并编写排查手册第 {k+1} 节。')
w('\n四、社团、志愿与兼职\n')
w('- 东临海事大学轮机协会　技术部部长（社团任职）　2020.09—2021.06：组织 6 次柴油机拆装实践活动，每次约 30 人参加。')
w('- 临江市海洋馆　讲解志愿者（志愿服务）　2021.07—2021.08：累计志愿服务 80 小时。')
w('- 某教育机构　数学家教（兼职）　2022.03—2022.12：辅导 3 名初中学生。\n')
w('五、项目经历\n')
w('1. Low-cost Smart Stethoscope for Clinical Training（中文名：用于临床教学的低成本智能听诊器，简称「智能听诊器」）\n硕士核心项目，2026.03—2026.11。包含需求分析、结构设计、样机制作、嵌入式软件、对比实验与会议论文。\n')
for k in range(14): w(f'- 第 {k+1} 阶段工作：完成听诊头声学腔体第 {k+1} 版迭代，测试信噪比并与商用设备对比，记录实验数据与改进方向；同步编写嵌入式滤波程序与上位机界面的对应模块。')
w('会议论文：“A Low-cost Smart Stethoscope for Clinical Training”（已投稿，录用状态待核实）。\n')
w('2. 基于 AMESim 的减压阀动态性能分析（Dynamic Performance Analysis of a Pressure Reducing Valve Using AMESim）\n本科毕业设计核心项目，2022.12—2023.05。\n')
for k in range(10): w(f'- 建立减压阀 AMESim 模型第 {k+1} 部分，分析阀芯质量、弹簧刚度、阻尼孔直径等参数对动态响应的影响，并整理仿真曲线与结论。')
w('（本科 AMESim 毕业设计的论文题目即上面的英文题目，答辩成绩：优秀。）\n')
w('3. 课程实验：液压回路搭建（辅助项目，课程实验）2021.10—2021.12\n- 按指导书搭建调速回路并记录数据。\n')
w('4. 教学实训：工业机器人示教编程（辅助项目，教学实训）2022.07\n- 完成码垛示教程序。\n')
w('5. 个人求职简历工具（辅助项目，个人小工具）2026.09—至今\n- 用 TypeScript 编写本地简历整理工具。\n')
w('六、技能\nPLC（西门子 S7-1200）、AMESim、SolidWorks、Python、C 语言、MATLAB、英语（雅思 6.5）\n')
w('七、证书\n- 轮机工程相关职业资格证书（证书编号待补充）\n- 全国大学英语六级\n')
w('八、获奖\n- 2021 年 校级二等奖学金\n- 2022 年 模拟省大学生机械创新设计大赛 三等奖\n')
w('九、证据材料\n- 成绩单扫描件：D:/资料/成绩单.pdf，证明 76 门课程成绩\n- 实习证明：邮箱附件，证明北岭生物实习经历\n- 会议论文投稿记录：投稿系统截图\n')
w('十、补充说明（流水账）\n')
pad='以上经历按时间顺序整理，部分内容为回忆，日期以证明材料为准。'
txt='\n'.join(out)
while len(txt)<13600: txt+='\n'+pad+f'（补充第 {txt.count(pad)+1} 条：在实习和项目中养成了记录实验日志的习惯，每周整理一次问题清单与改进方案。）'
open(os.path.join(os.path.dirname(__file__),'files','mock_master_profile_zh.txt'),'w').write(txt)
print(len(txt))
